mapper.select:
SELECT * FROM batch_transfer_ledger
WHERE 1=1
AND operator LIKE CONCAT('%', #{operator}, '%')
AND transfer_time >= #{startTime}
AND transfer_time <= #{endTime}
AND batch_no LIKE CONCAT('%', #{batchNo}, '%')
AND settle_status = #{settleStatus}
ORDER BY transfer_time DESC

mapper.update:
UPDATE batch_transfer_ledger
SET settle_status = 'CLOSED',
    settled_by = #{operator},
    settled_at = #{time}
WHERE id = #{id}
  AND settle_status = 'OPEN'

mapper.select:
SELECT DISTINCT * FROM ( SELECT 'TRANSFER_LEDGER' AS type, '未核销划转流水' AS typeText, l.id AS refId, l.batch_no AS refNo, d.source_zone_id AS zoneId, gz.zone_name AS zoneName, l.settle_status AS status, '未核销' AS statusText, CONCAT('划转流水[', l.batch_no, ']的源分区仍指向该分区且尚未核销，请先核销流水后再删除') AS detail, DATE_FORMAT(l.transfer_time, '%Y-%m-%d %H:%i:%s') AS bizTime FROM batch_transfer_ledger l INNER JOIN ledger_detail d ON d.ledger_id = l.id LEFT JOIN garage_zone gz ON gz.id = d.source_zone_id WHERE l.settle_status = 'OPEN' AND d.source_zone_id IN
#{zoneId}
UNION ALL
SELECT 'TRANSFER_LEDGER' AS type, '未核销划转流水' AS typeText, l.id AS refId, l.batch_no AS refNo, l.target_zone_id AS zoneId, gz2.zone_name AS zoneName, l.settle_status AS status, '未核销' AS statusText, CONCAT('划转流水[', l.batch_no, ']的目标分区仍指向该分区且尚未核销，请先核销流水后再删除') AS detail, DATE_FORMAT(l.transfer_time, '%Y-%m-%d %H:%i:%s') AS bizTime FROM batch_transfer_ledger l LEFT JOIN garage_zone gz2 ON gz2.id = l.target_zone_id WHERE l.settle_status = 'OPEN' AND l.target_zone_id IN
#{zoneId}
) t ORDER BY t.bizTime DESC, t.refId DESC, t.zoneId
